#!/usr/bin/env python3
"""Self-test for a stdio MCP code-analysis server.

Speaks raw newline-delimited JSON-RPC, so it needs no MCP SDK and works on any
Python 3.8+. Generates its own tiny Python fixture, then asserts the server
actually analyses it.

Usage:
    python verify-mcp.py <server-command> [args...]
    python verify-mcp.py --expect get_symbol_signature,get_symbol_dependencies ./repodigest-mcp

Exit code 0 means every check passed.
"""

import argparse
import json
import os
import subprocess
import sys
import tempfile
import threading

FIXTURE = '''\
"""Fixture generated by verify-mcp.py."""


def load_rows(path):
    """Read rows from a file."""
    with open(path, encoding="utf-8") as handle:
        return [line.strip() for line in handle if line.strip()]


class RowStore:
    """In-memory store."""

    def __init__(self):
        self.rows = []

    def add(self, row):
        """Append one row."""
        self.rows.append(row)
        return len(self.rows)


def build_store(rows):
    """Build a RowStore from an iterable of rows."""
    store = RowStore()
    for row in rows:
        store.add(row)
    return store
'''


class Probe:
    def __init__(self, command, timeout=60):
        self.proc = subprocess.Popen(
            command,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="replace",
            bufsize=1,
        )
        self.timeout = timeout
        self.stderr = []
        threading.Thread(target=self._drain, daemon=True).start()
        self._next_id = 0

    def _drain(self):
        for line in self.proc.stderr:
            self.stderr.append(line.rstrip())

    def request(self, method, params=None):
        self._next_id += 1
        rid = self._next_id
        payload = {"jsonrpc": "2.0", "id": rid, "method": method}
        if params is not None:
            payload["params"] = params
        self.proc.stdin.write(json.dumps(payload) + "\n")
        self.proc.stdin.flush()
        for _ in range(5000):
            line = self.proc.stdout.readline()
            if not line:
                raise RuntimeError("server closed stdout while waiting for %s" % method)
            line = line.strip()
            if not line:
                continue
            try:
                msg = json.loads(line)
            except json.JSONDecodeError:
                continue
            if msg.get("id") == rid:
                if "error" in msg:
                    raise RuntimeError("%s failed: %s" % (method, msg["error"]))
                return msg.get("result", {})
        raise RuntimeError("no reply for %s" % method)

    def notify(self, method, params=None):
        payload = {"jsonrpc": "2.0", "method": method}
        if params is not None:
            payload["params"] = params
        self.proc.stdin.write(json.dumps(payload) + "\n")
        self.proc.stdin.flush()

    def close(self):
        try:
            self.proc.terminate()
            self.proc.wait(timeout=5)
        except Exception:
            self.proc.kill()


def text_of(result):
    out = []
    for block in result.get("content", []) or []:
        if block.get("type") == "text":
            out.append(block.get("text", ""))
    return "".join(out)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("command", nargs=argparse.REMAINDER, help="server command and arguments")
    ap.add_argument("--expect", default="", help="comma-separated tool names that must be present")
    ap.add_argument("--skip-tool-call", action="store_true", help="only check handshake and tool list")
    args = ap.parse_args()

    command = args.command
    if command and command[0] == "--":
        command = command[1:]
    if not command:
        print("usage: verify-mcp.py [--expect a,b] [--skip-tool-call] <command> [args...]", file=sys.stderr)
        return 2

    expected = [name.strip() for name in args.expect.split(",") if name.strip()]
    checks = []

    def check(label, ok, detail=""):
        checks.append(ok)
        print("[%s] %s%s" % ("PASS" if ok else "FAIL", label, ("  " + detail) if detail else ""))

    fixture_dir = tempfile.mkdtemp(prefix="verify-mcp-")
    fixture_path = os.path.join(fixture_dir, "fixture_mod.py")
    with open(fixture_path, "w", encoding="utf-8") as handle:
        handle.write(FIXTURE)

    probe = None
    try:
        probe = Probe(command)
        info = probe.request(
            "initialize",
            {
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {"name": "verify-mcp", "version": "1.0"},
            },
        )
        server = info.get("serverInfo", {}) or {}
        check("initialize", True, "server=%s %s" % (server.get("name"), server.get("version", "")))

        probe.notify("notifications/initialized")
        tools = [t.get("name") for t in (probe.request("tools/list").get("tools") or [])]
        check("tools/list", bool(tools), "tools=" + ",".join(tools))

        missing = [name for name in expected if name not in tools]
        if expected:
            check("expected tools present", not missing, "missing=" + ",".join(missing) if missing else "")

        if not args.skip_tool_call and "get_symbol_signature" in tools:
            result = probe.request(
                "tools/call",
                {
                    "name": "get_symbol_signature",
                    "arguments": {"symbol_name": "fixture_mod.build_store", "path": fixture_dir},
                },
            )
            body = text_of(result)
            check(
                "tools/call get_symbol_signature",
                bool(body.strip()) and not result.get("isError"),
                body.strip().splitlines()[0] if body.strip() else "",
            )

        if not args.skip_tool_call and "get_symbol_dependencies" in tools:
            result = probe.request(
                "tools/call",
                {
                    "name": "get_symbol_dependencies",
                    "arguments": {"symbol_name": "fixture_mod.build_store", "path": fixture_dir},
                },
            )
            body = text_of(result)
            check(
                "tools/call get_symbol_dependencies",
                "RowStore" in body,
                "call graph reached the fixture class" if "RowStore" in body else body.strip()[:120],
            )

        if not args.skip_tool_call and "pack_task_context" in tools:
            result = probe.request(
                "tools/call",
                {
                    "name": "pack_task_context",
                    "arguments": {
                        "query": "build a store from rows",
                        "budget": 600,
                        "signatures_only": True,
                        "path": fixture_dir,
                    },
                },
            )
            body = text_of(result)
            check("tools/call pack_task_context", bool(body.strip()) and not result.get("isError"), body.strip()[:80])
    except Exception as exc:  # noqa: BLE001 - report any failure as a failed check
        check("probe", False, "%s: %s" % (type(exc).__name__, exc))
    finally:
        if probe is not None:
            if probe.stderr:
                print("[stderr] " + " | ".join(probe.stderr[:6]))
            probe.close()

    ok = all(checks)
    print("[RESULT] " + ("ALL PASS" if ok else "FAILED"))
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
